// Helper method to count occurrences of strings containing a substring
method Count(strings: seq<string>, substring: string) returns (count: int)
    requires |strings| >= 0
    requires substring != null
    ensures count >= 0
{
    count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant count == Count(strings[0..i], substring)
    {
        if substring in strings[i] {
            count := count + 1;
        }
        i := i + 1;
    }
}
